window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-a3f985d28dedf4e4"]={"versions": [{"id": "FIG-a3f985d28dedf4e4", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Schichtenarchitektur-Diagramm der AUTOSAR Basic Software (BSW) mit Fokus auf die LIN-relevanten Module. Dargestellt ist die vertikale Gliederung der Architektur in Service-Schicht (blauviolett hinterlegt), Communication Hardware Abstraction (grün hinterlegt), Microcontroller Abstraction Layer (MCAL) unterteilt in I/O Drivers und Communication Drivers (hellrot hinterlegt) sowie die darunterliegende Mikrocontroller-Hardwareebene (µC, schwarz). Die Farbcodierung der Module unterscheidet LIN-spezifische Module (blau) von allgemeinen AUTOSAR-BSW-Modulen (orange) sowie der Hardware-Ebene (silber/grau).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm enthält folgende Komponenten und Schnittstellenbeziehungen:</p>\n<ul class=\"fig-list\"><li>Obere Services-Ebene: AUTOSAR COM, IPDU Multiplexer („IPDU Multiple xer“), PDU Router or Complex Device Driver, Diagnostic Communication Manager („Diagno stic Com. Manag er“), Debugging sowie die LIN-spezifischen Komponenten LIN State Manager or Complex Device Driver und LIN NM or Complex Device Driver.\n</li><li>Communication Hardware Abstraction: LIN Interface (inc. LinTp), welches L-förmig geschnitten ist und sowohl an PDU Router / Complex Device Driver als auch direkt an LIN State Manager / Complex Device Driver und LIN NM / Complex Device Driver grenzt; LIN Transceiver Driver unterhalb des linken Teils des LIN Interface.\n</li><li>Microcontroller Abstraction Layer (MCAL):\n<ul class=\"fig-list\"><li>I/O Drivers: DIO Driver (orange).\n</li><li>Communication Drivers: LIN Driver 1 und LIN Driver 2 (beide blau).\n</li></ul>\n</li><li>Mikrocontroller-Ebene (µC): LIN 1 und LIN 2 Hardware-Controller.\n</li></ul>\n<p class=\"fig-p\">Die physische und logische Schichtung impliziert vertikale Schnittstellen zwischen AUTOSAR COM / Dcm und PDU Router, PDU Router und LIN Interface, LIN State Manager / LIN NM und LIN Interface, LIN Interface zu LIN Transceiver Driver und LIN Driver 1/2 sowie LIN Transceiver Driver zu DIO Driver bzw. LIN Driver zu den Controllern.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm visualisiert eine statische Komponenten- und Schichtungsübersicht ohne explizite Ablauf- oder Sequenzpfade. Dynamische Abläufe ergeben sich aus der vertikalen Kopplung: PDU-Weiterleitung von AUTOSAR COM / Dcm über den PDU Router an das LIN Interface; Zustands- und Netzwerkmanagement-Signalisierung über den LIN State Manager bzw. LIN NM an das LIN Interface; Routing von LIN-Frames über die LIN-Treiber zur Hardware bzw. Steuerung externer Transceiver über Transceiver-Treiber und DIO.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Architektonische Übersichtsdarstellung zur Abgrenzung der BSW-Komponenten im LIN-Subsystem gemäß AUTOSAR-Spezifikation. Definiert die Zuordnung von LIN Interface (inkl. Transportprotokoll LinTp), LIN State Manager, LIN NM, Transceiver Driver und LIN Driver zu den normativen AUTOSAR-Schichten sowie die zulässigen vertikalen Interaktionsgrenzen und Complex-Device-Driver-Bypass-Pfade.</p>"}, {"id": "FIG-18889ccf1150bd76", "releases": ["R4.1.3", "R4.2.2", "R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Schichtenarchitektur-Diagramm der AUTOSAR Basic Software (BSW) mit Fokus auf die LIN-relevanten Module. Dargestellt ist die vertikale Gliederung der Architektur in Service-Schicht (blauviolett hinterlegt), Communication Hardware Abstraction (grün hinterlegt), Microcontroller Abstraction Layer (MCAL) unterteilt in I/O Drivers und Communication Drivers (hellrot hinterlegt) sowie die darunterliegende Mikrocontroller-Hardwareebene (µC, schwarz). Die Farbcodierung der Module unterscheidet LIN-spezifische Module (blau) von allgemeinen AUTOSAR-BSW-Modulen (orange) sowie der Hardware-Ebene (silber/grau).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm enthält folgende Komponenten und Schnittstellenbeziehungen:</p>\n<ul class=\"fig-list\"><li>Obere Services-Ebene: AUTOSAR COM, IPDU Multiplexer („IPDU Multiple xer“), PDU Router or Complex Driver, Diagnostic Communication Manager („Diagno stic Com. Manag er“), Debugging sowie die LIN-spezifischen Komponenten LIN State Manager or Complex Driver und LIN NM or Complex Driver.\n</li><li>Communication Hardware Abstraction: LIN Interface (inc. LIN TP), welches L-förmig geschnitten ist und an PDU Router or Complex Driver, LIN State Manager or Complex Driver und LIN NM or Complex Driver grenzt; LIN Transceiver Driver unterhalb des linken Teils des LIN Interface.\n</li><li>Microcontroller Abstraction Layer (MCAL):\n<ul class=\"fig-list\"><li>I/O Drivers: DIO Driver (orange).\n</li><li>Communication Drivers: LIN Driver 1 und LIN Driver 2 (beide blau).\n</li></ul>\n</li><li>Mikrocontroller-Ebene (µC): LIN 1 und LIN 2 Hardware-Controller (korrekt unter LIN Driver 1 bzw. LIN Driver 2 angeordnet).\n</li></ul>\n<p class=\"fig-p\">Die Schichtung definiert vertikale Schnittstellen zwischen den Service-Modulen (PDU Router, LIN State Manager, LIN NM) und dem LIN Interface, vom LIN Interface zum LIN Transceiver Driver und den LIN-Treibern sowie von den Treiber-Modulen zu DIO Driver und Hardware-Controllern.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm visualisiert eine statische Komponenten- und Schichtungsübersicht ohne explizite Ablauf- oder Sequenzpfade. Dynamische Abläufe ergeben sich aus der vertikalen Kopplung: PDU-Weiterleitung von AUTOSAR COM / Dcm über den PDU Router an das LIN Interface; Zustands- und Netzwerkmanagement-Signalisierung über den LIN State Manager bzw. LIN NM an das LIN Interface; Routing von LIN-Frames über die LIN-Treiber zur Hardware bzw. Steuerung externer Transceiver über Transceiver-Treiber und DIO.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Architektonische Übersichtsdarstellung zur Abgrenzung der BSW-Komponenten im LIN-Subsystem gemäß AUTOSAR-Spezifikation. Definiert die Zuordnung von LIN Interface (inkl. Transportprotokoll LinTp), LIN State Manager, LIN NM, Transceiver Driver und LIN Driver zu den normativen AUTOSAR-Schichten sowie die zulässigen vertikalen Interaktionsgrenzen und Complex-Device-Driver-Bypass-Pfade.</p>"}, {"id": "FIG-5b1aeec5e616b58b", "releases": ["R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Schichtenarchitektur-Diagramm der AUTOSAR Basic Software (BSW) mit Fokus auf die LIN-relevanten Module. Dargestellt ist die vertikale Gliederung der Architektur in Service-Schicht (blauviolett hinterlegt), Communication Hardware Abstraction (grün hinterlegt), Microcontroller Abstraction Layer (MCAL) unterteilt in I/O Drivers und Communication Drivers (hellrot hinterlegt) sowie die darunterliegende Mikrocontroller-Hardwareebene (µC, schwarz). Die Farbcodierung der Module unterscheidet LIN-spezifische Module (blau) von allgemeinen AUTOSAR-BSW-Modulen (orange) sowie der Hardware-Ebene (silber/grau).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm enthält folgende Komponenten und Schnittstellenbeziehungen:</p>\n<ul class=\"fig-list\"><li>Obere Services-Ebene: AUTOSAR COM, IPDU Multiplexer („IPDU Multiple xer“), PDU Router or Complex Driver, Diagnostic Communication Manager („Diagno stic Com. Manag er“) sowie die LIN-spezifische Komponente LIN State Manager or Complex Driver. Die Module Debugging und LIN NM or Complex Driver sind nicht mehr vorhanden.\n</li><li>Communication Hardware Abstraction: LIN Interface (inc. LIN TP), welches an PDU Router or Complex Driver und LIN State Manager or Complex Driver grenzt; LIN Transceiver Driver unterhalb des linken Teils des LIN Interface.\n</li><li>Microcontroller Abstraction Layer (MCAL):\n<ul class=\"fig-list\"><li>I/O Drivers: DIO Driver.\n</li><li>Communication Drivers: LIN Driver 1 und LIN Driver 2.\n</li></ul>\n</li><li>Mikrocontroller-Ebene (µC): LIN 1 und LIN 2 Hardware-Controller.\n</li></ul>\n<p class=\"fig-p\">Vertikale Schnittstellen verlaufen zwischen AUTOSAR COM / Dcm und PDU Router, PDU Router und LIN Interface, LIN State Manager und LIN Interface sowie LIN Interface zu LIN Transceiver Driver und den LIN-Treibern.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm visualisiert eine statische Komponenten- und Schichtungsübersicht ohne explizite Ablauf- oder Sequenzpfade. Dynamische Abläufe ergeben sich aus der vertikalen Kopplung: PDU-Weiterleitung von AUTOSAR COM / Dcm über den PDU Router an das LIN Interface; Zustands- und Netzwerkmanagement-Signalisierung über den LIN State Manager bzw. LIN NM an das LIN Interface; Routing von LIN-Frames über die LIN-Treiber zur Hardware bzw. Steuerung externer Transceiver über Transceiver-Treiber und DIO.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Architektonische Übersichtsdarstellung zur Abgrenzung der BSW-Komponenten im LIN-Subsystem. Bestimmt die normative Einbettung des LIN Interface (inkl. Transportprotokoll LIN TP) und LIN State Managers; belegt den Wegfall von LIN NM und Debugging-Schnittstellen aus dem Standard-LIN-Kommunikationsstack der BSW.</p>"}, {"id": "FIG-db131446924045ff", "releases": ["R19-11", "R20-11", "R21-11", "R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Schichtenarchitektur-Diagramm der AUTOSAR Basic Software (BSW) mit Fokus auf die LIN-relevanten Module. Dargestellt ist die vertikale Gliederung der Architektur in Service-Schicht (blauviolett hinterlegt), Communication Hardware Abstraction (grün hinterlegt), Microcontroller Abstraction Layer (MCAL) unterteilt in I/O Drivers und Communication Drivers (hellrot hinterlegt) sowie die darunterliegende Mikrocontroller-Hardwareebene (µC, schwarz). Die Farbcodierung der Module unterscheidet LIN-spezifische Module (blau) von allgemeinen AUTOSAR-BSW-Modulen (orange) sowie der Hardware-Ebene (silber/grau).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm enthält folgende Komponenten und Schnittstellenbeziehungen:</p>\n<ul class=\"fig-list\"><li>Obere Services-Ebene: AUTOSAR COM, IPDU Multiplexer („IPDU Multiple xer“), PDU Router or Complex Driver, Diagnostic Communication Manager („Diagno stic Com. Manag er“) sowie die LIN-spezifische Komponente LIN State Manager or Complex Driver.\n</li><li>Communication Hardware Abstraction: LIN Interface (incl. LIN TP), welches an PDU Router or Complex Driver und LIN State Manager or Complex Driver grenzt; LIN Transceiver Driver unterhalb des linken Teils des LIN Interface.\n</li><li>Microcontroller Abstraction Layer (MCAL):\n<ul class=\"fig-list\"><li>I/O Drivers: DIO Driver.\n</li><li>Communication Drivers: LIN Driver 1 und LIN Driver 2.\n</li></ul>\n</li><li>Mikrocontroller-Ebene (µC): LIN 1 und LIN 2 Hardware-Controller.\n</li></ul>\n<p class=\"fig-p\">Vertikale Schnittstellen verlaufen zwischen den Service-Modulen (PDU Router, LIN State Manager) und dem LIN Interface, vom LIN Interface zum LIN Transceiver Driver und den LIN-Treibern sowie zu den Hardware-Controllern.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm visualisiert eine statische Komponenten- und Schichtungsübersicht ohne explizite Ablauf- oder Sequenzpfade. Dynamische Abläufe ergeben sich aus der vertikalen Kopplung: PDU-Weiterleitung von AUTOSAR COM / Dcm über den PDU Router an das LIN Interface; Zustands- und Netzwerkmanagement-Signalisierung über den LIN State Manager bzw. LIN NM an das LIN Interface; Routing von LIN-Frames über die LIN-Treiber zur Hardware bzw. Steuerung externer Transceiver über Transceiver-Treiber und DIO.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Architektonische Übersichtsdarstellung zur Abgrenzung der BSW-Komponenten im LIN-Subsystem. Bestimmt die normative Einbettung des LIN Interface (inkl. Transportprotokoll LIN TP) und LIN State Managers; belegt den Wegfall von LIN NM und Debugging-Schnittstellen aus dem Standard-LIN-Kommunikationsstack der BSW.</p>"}, {"id": "FIG-f4e6e7a49c11c2d5", "releases": ["R23-11", "R24-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Schichtenarchitektur-Diagramm der AUTOSAR Basic Software (BSW) mit Fokus auf die LIN-relevanten Module. Dargestellt ist die vertikale Gliederung der Architektur in Service-Schicht (blauviolett hinterlegt), Communication Hardware Abstraction (grün hinterlegt), Microcontroller Abstraction Layer (MCAL) unterteilt in I/O Drivers und Communication Drivers (hellrot hinterlegt) sowie die darunterliegende Mikrocontroller-Hardwareebene (µC, schwarz). Die Farbcodierung der Module unterscheidet LIN-spezifische Module (blau) von allgemeinen AUTOSAR-BSW-Modulen (orange) sowie der Hardware-Ebene (silber/grau).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm enthält folgende Komponenten und Schnittstellenbeziehungen:</p>\n<ul class=\"fig-list\"><li>Communication Services: AUTOSAR COM, IPDU Multiplexer, PDU Router or Complex Driver, Diagnostic Communication Manager (senkrecht ausgerichtet) sowie LIN State Manager or Complex Driver.\n</li><li>Communication Hardware Abstraction: LIN Interface (incl. LIN TP), LIN Transceiver Driver sowie Driver for ext. LIN ASIC. Der Block „Driver for ext. LIN ASIC“ ist neben dem LIN Transceiver Driver unterhalb des LIN Interface platziert.\n</li><li>Microcontroller Abstraction Layer (MCAL):\n<ul class=\"fig-list\"><li>I/O Drivers: DIO Driver.\n</li><li>Communication Drivers: LIN Driver 1 und LIN Driver 2.\n</li></ul>\n</li><li>Mikrocontroller-Ebene (µC): LIN 1 und LIN 2 Hardware-Controller.\n</li></ul>\n<p class=\"fig-p\">Schnittstellenbeziehungen umfassen PDU Router und LIN State Manager zum LIN Interface, LIN Interface zu LIN Transceiver Driver, Driver for ext. LIN ASIC und LIN Driver 1/2 sowie LIN Transceiver Driver zu DIO Driver und LIN Driver zu den Hardware-Controllern.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm stellt eine statische Schichtenarchitektur dar. Dynamisch zeigt die Erweiterung um den externen LIN-ASIC-Treiber zusätzliche Abstraktionspfade: Die LIN-Kommunikation kann wahlweise über on-chip LIN-Controller (LIN Driver 1/2) oder über externe LIN-ASICs (Driver for ext. LIN ASIC) abgewickelt werden, gesteuert durch das übergeordnete LIN Interface.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Architektonische Übersichtsdarstellung zur normativen Abgrenzung der LIN-BSW-Module. Etabliert die normative Unterstützung für externe LIN-ASICs über eine dedizierte Treiberkomponente („Driver for ext. LIN ASIC“) in der Communication Hardware Abstraction Schicht unterhalb des LIN Interface.</p>"}], "trans": [{"from": "FIG-a3f985d28dedf4e4", "to": "FIG-18889ccf1150bd76", "fr": "R4.0.3", "tr": "R4.1.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Umbenennung von „LIN State Manager or Complex Device Driver“ zu „LIN State Manager or Complex Driver“ durch Tilgung des Worts „Device“.\n</li><li>Umbenennung von „LIN NM or Complex Device Driver“ zu „LIN NM or Complex Driver“ durch Tilgung des Worts „Device“.\n</li><li>Umbenennung von „PDU Router or Complex Device Driver“ zu „PDU Router or Complex Driver“ durch Tilgung des Worts „Device“.\n</li><li>Vereinheitlichung der Schreibweise im Modulblock des LIN-Interface von „LIN Interface (inc. LinTp)“ zu „LIN Interface (inc. LIN TP)“.\n</li><li>Vertauschung bzw. Korrektur der Beschriftungsanordnung der Hardware-Controller-Blöcke im unteren Bereich (vormals „LIN 1 LIN 2“, nun konsistent zu den Treibern ausgerichtet als „LIN 1“ links und „LIN 2“ rechts).\n</li></ul>"}, {"from": "FIG-18889ccf1150bd76", "to": "FIG-5b1aeec5e616b58b", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Entfernung des Moduls „LIN NM or Complex Driver“ aus der Schicht der Kommunikationsdienste.\n</li><li>Entfernung des Moduls „Debugging“ aus der Schicht der Kommunikationsdienste.\n</li></ul>"}, {"from": "FIG-5b1aeec5e616b58b", "to": "FIG-db131446924045ff", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Textuelle Korrektur im Modulblock des LIN-Interface von „LIN Interface (inc. LIN TP)“ zu „LIN Interface (incl. LIN TP)“.\n</li></ul>"}, {"from": "FIG-db131446924045ff", "to": "FIG-f4e6e7a49c11c2d5", "fr": "R22-11", "tr": "R23-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Hinzufügung des Modulblocks „Driver for ext. LIN ASIC“ innerhalb der Kommunikations-Hardware-Abstraktionsschicht („Communication Hardware Abstraction“) neben dem „LIN Transceiver Driver“.\n</li><li>Ergänzung der expliziten Schichtbeschriftung „Communication Services“ am oberen Rand des Services-Blocks.\n</li><li>Korrektur der Schreibweise von „IPDU Multiplexer“ (vormals getrennt „IPDU Multiple xer“).\n</li><li>Änderung der Textausrichtung im Block „Diagnostic Communication Manager“ (vormals getrennt „Diagno stic Com. Manag er“).\n</li></ul>"}]};
